/* jacobi-2d.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

#ifdef _OPENMP
# include <omp.h>
#endif

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "jacobi-2d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  for (i = 0; i < n; i++)
  {
    /* Use row pointers to improve spatial locality and reduce
       address arithmetic inside the inner loop. */
    DATA_TYPE * restrict Ai = &A[i][0];
    DATA_TYPE * restrict Bi = &B[i][0];

    for (j = 0; j < n; j++)
    {
      Ai[j] = ((DATA_TYPE) i*(j+2) + 2) / n;
      Bi[j] = ((DATA_TYPE) i*(j+3) + 3) / n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Hoist constant SCALAR_VAL(0.2) out of inner loops.
   - Use row pointers (with restrict) to reduce address computations and
     help the compiler vectorize.
   - Parallelize the spatial loops with OpenMP.
     * One parallel region surrounds the full time-stepping loop so that
       threads are created only once.
     * 'omp for' distributes rows among threads.
     * 'omp simd' on the inner loop encourages explicit SIMD vectorization.
   - Preserve original iteration bounds and computation order to keep
     numerical behavior identical.
*/
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  /* One parallel region over the whole time loop to amortize
     thread creation costs. If compiled without OpenMP support,
     these pragmas are ignored and the code runs sequentially. */
#pragma omp parallel private(t, i, j)
  {
    /* Constant stencil weight; computed once per thread. */
    const DATA_TYPE c0_2 = SCALAR_VAL(0.2);

    /* Effective interior bounds:
       original loops run i,j = 1 .. (_PB_N - 2). */
    const int n_inner      = _PB_N - 1;
    const int tsteps_inner = _PB_TSTEPS;

    for (t = 0; t < tsteps_inner; t++)
    {
      /* First sweep: update B using A.
         Each (i,j) update reads only from A and writes to a unique B[i][j],
         so rows can be distributed across threads safely. */
#pragma omp for schedule(static)
      for (i = 1; i < n_inner; i++)
      {
        /* Row pointers improve cache locality and reduce the cost of
           computing 2D indices repeatedly. 'restrict' expresses that
           these pointers do not alias each other, enabling better
           vectorization and instruction scheduling. */
        DATA_TYPE       * restrict Bi   = &B[i][0];
        const DATA_TYPE * restrict Ai   = &A[i][0];
        const DATA_TYPE * restrict Aim1 = &A[i-1][0];
        const DATA_TYPE * restrict Aip1 = &A[i+1][0];

        /* Inner loop is purely data-parallel: one stencil update per
           interior point. 'omp simd' explicitly allows the compiler
           to generate SIMD instructions across j. */
#pragma omp simd
        for (j = 1; j < n_inner; j++)
        {
          Bi[j] = c0_2 * (Ai[j]     +
                          Ai[j-1]   +
                          Ai[j+1]   +
                          Aip1[j]   +
                          Aim1[j]);
        }
      }

      /* Second sweep: update A using B, with the same stencil pattern.
         Dependencies are only through B, and each A[i][j] is written once. */
#pragma omp for schedule(static)
      for (i = 1; i < n_inner; i++)
      {
        DATA_TYPE       * restrict Ai   = &A[i][0];
        const DATA_TYPE * restrict Bi   = &B[i][0];
        const DATA_TYPE * restrict Bim1 = &B[i-1][0];
        const DATA_TYPE * restrict Bip1 = &B[i+1][0];

#pragma omp simd
        for (j = 1; j < n_inner; j++)
        {
          Ai[j] = c0_2 * (Bi[j]     +
                          Bi[j-1]   +
                          Bi[j+1]   +
                          Bip1[j]   +
                          Bim1[j]);
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
