 *
 * to better match a specific cache hierarchy.
 * ------------------------------------------------------------------*/
#ifndef JACOBI_2D_TILE_I
# define JACOBI_2D_TILE_I 32
#endif

#ifndef JACOBI_2D_TILE_J
# define JACOBI_2D_TILE_J 32
#endif


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int i, j;

  /* Restrict-qualified local aliases help the compiler reason about
     aliasing and optimize memory accesses. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Row-major traversal already has good spatial locality. We simply
     make it easy for the compiler (and OpenMP, when enabled) to
     optimize this double loop. */
#ifdef _OPENMP
# pragma omp parallel for collapse(2) schedule(static)
#endif
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      {
	A_[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B_[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local pointers for A and B to enable
     better vectorization and alias analysis.
   - Hoist loop-invariant values (_PB_N, _PB_TSTEPS, stencil weight).
   - Apply 2D spatial blocking (tiling) in i and j to improve cache
     locality when traversing the large N x N grids.
   - Parallelize the spatial loops with OpenMP when available. A
     single parallel region around the time loop avoids repeated
     thread creation/destruction. Implicit barriers at the end of
     each omp for ensure that the B-sweep is completed before the
     A-sweep for a given time step.
 */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* Local restrict-qualified aliases to improve compiler optimization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  /* Hoist loop bounds and constant factor out of the hot loops. */
  const int tsteps_ = _PB_TSTEPS;
  const int n_      = _PB_N;
  const DATA_TYPE c = SCALAR_VAL(0.2);

#pragma scop
  /* Outer parallel region (created only if compiled with OpenMP). */
#ifdef _OPENMP
# pragma omp parallel
#endif
  {
    for (int t = 0; t < tsteps_; ++t)
    {
      /* ----------------------------------------------------------------
       * First sweep: update B from A.
       *  B[i][j] = 0.2 * (A[i][j] + A[i][j-1] + A[i][j+1]
       *                    + A[i+1][j] + A[i-1][j])
       *
       * The computation for each (i,j) in the interior (1..n_-2) depends
       * only on A, which is read-only in this sweep. Therefore, the
       * iteration space can be freely tiled and parallelized without
       * changing the numerical result.
       * --------------------------------------------------------------*/
#ifdef _OPENMP
#     pragma omp for collapse(2) schedule(static)
#endif
      for (int ii = 1; ii < n_ - 1; ii += JACOBI_2D_TILE_I)
        for (int jj = 1; jj < n_ - 1; jj += JACOBI_2D_TILE_J)
        {
          const int i_max = (ii + JACOBI_2D_TILE_I < n_ - 1) ? (ii + JACOBI_2D_TILE_I) : (n_ - 1);
          const int j_max = (jj + JACOBI_2D_TILE_J < n_ - 1) ? (jj + JACOBI_2D_TILE_J) : (n_ - 1);

          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
              B_[i][j] = c * (A_[i][j] +
                              A_[i][j-1] + A_[i][j+1] +
                              A_[i+1][j] + A_[i-1][j]);
        }

      /* ----------------------------------------------------------------
       * Second sweep: update A from B.
       *  A[i][j] = 0.2 * (B[i][j] + B[i][j-1] + B[i][j+1]
       *                    + B[i+1][j] + B[i-1][j])
       *
       * Here B is read-only and A is written, so the same tiling and
       * parallelization strategy is valid and preserves semantics.
       * The implicit barrier at the end of the previous omp for
       * guarantees that the entire B grid for time step t is complete.
       * --------------------------------------------------------------*/
#ifdef _OPENMP
#     pragma omp for collapse(2) schedule(static)
#endif
      for (int ii = 1; ii < n_ - 1; ii += JACOBI_2D_TILE_I)
        for (int jj = 1; jj < n_ - 1; jj += JACOBI_2D_TILE_J)
        {
          const int i_max = (ii + JACOBI_2D_TILE_I < n_ - 1) ? (ii + JACOBI_2D_TILE_I) : (n_ - 1);
          const int j_max = (jj + JACOBI_2D_TILE_J < n_ - 1) ? (jj + JACOBI_2D_TILE_J) : (n_ - 1);

          for (int i = ii; i < i_max; ++i)
            for (int j = jj; j < j_max; ++j)
              A_[i][j] = c * (B_[i][j] +
                              B_[i][j-1] + B_[i][j+1] +
                              B_[i+1][j] + B_[i-1][j]);
        }
      /* Implicit barrier here (end of omp for) ensures all A-updates
         for time step t are complete before the next t iteration. */
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
