    for (j = 0; j < n; j++)
      {
	A_[i][j] = ((DATA_TYPE) i*(j+2) + 2) / n;
	B_[i][j] = ((DATA_TYPE) i*(j+3) + 3) / n;
      }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      if ((i * n + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j]);
    }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

  /* Local restrict-qualified views to improve alias analysis and
     enable better vectorization.  The layout and bounds are exactly
     the same as in the original code. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*restrict)[n]) A;
  DATA_TYPE (*restrict B_)[n] = (DATA_TYPE (*restrict)[n]) B;

  /* Hoist loop-invariant values into local scalars.
     _PB_TSTEPS and _PB_N are PolyBench macros that encode the
     actual loop bounds (possibly depending on 'tsteps' and 'n'). */
  const DATA_TYPE c0_2  = SCALAR_VAL(0.2);
  const int tstepsPB    = _PB_TSTEPS;
  const int nPB         = _PB_N;
  const int istart      = 1;
  const int iend        = nPB - 1;
  const int jstart      = 1;
  const int jend        = nPB - 1;

#pragma scop
  /* Parallelize the spatial sweeps with OpenMP.  A single parallel
     region surrounds all time steps to reduce threading overhead.
     Each 'omp for' loop has an implicit barrier at the end, which
     preserves the original sequential ordering:
       1) compute B from A
       2) compute A from B
     for every time step 't'. */
#ifdef _OPENMP
#pragma omp parallel private(t, i, j)
#endif
  {
    for (t = 0; t < tstepsPB; t++)
    {
      /* First sweep: B <= stencil(A).  Work is split over rows. */
#ifdef _OPENMP
#pragma omp for schedule(static, JACOBI_2D_OMP_CHUNK)
#endif
      for (i = istart; i < iend; i++)
      {
        DATA_TYPE *restrict Ai   = A_[i];
        DATA_TYPE *restrict Aim1 = A_[i-1];
        DATA_TYPE *restrict Aip1 = A_[i+1];
        DATA_TYPE *restrict Bi   = B_[i];

        /* The inner loop is fully vectorizable: each iteration writes
           a distinct Bi[j] and only reads from A_.  The GCC 'ivdep'
           pragma states that there are no loop-carried dependencies. */
#pragma GCC ivdep
        for (j = jstart; j < jend; j++)
        {
          /* Order of operations matches the original expression:
             A[i][j] + A[i][j-1] + A[i][j+1] + A[i+1][j] + A[i-1][j] */
          Bi[j] = c0_2 *
                  (Ai[j]    +   /* center */
                   Ai[j-1]  +   /* left   */
                   Ai[j+1]  +   /* right  */
                   Aip1[j]  +   /* down   (i+1) */
                   Aim1[j]);    /* up     (i-1) */
        }
      }

      /* Second sweep: A <= stencil(B). */
#ifdef _OPENMP
#pragma omp for schedule(static, JACOBI_2D_OMP_CHUNK)
#endif
      for (i = istart; i < iend; i++)
      {
        DATA_TYPE *restrict Bi   = B_[i];
        DATA_TYPE *restrict Bim1 = B_[i-1];
        DATA_TYPE *restrict Bip1 = B_[i+1];
        DATA_TYPE *restrict Ai   = A_[i];

#pragma GCC ivdep
        for (j = jstart; j < jend; j++)
        {
          /* Order of operations matches the original expression:
             B[i][j] + B[i][j-1] + B[i][j+1] + B[i+1][j] + B[i-1][j] */
          Ai[j] = c0_2 *
                  (Bi[j]    +   /* center */
                   Bi[j-1]  +   /* left   */
                   Bi[j+1]  +   /* right  */
                   Bip1[j]  +   /* down   (i+1) */
                   Bim1[j]);    /* up     (i-1) */
        }
      }
    } /* time loop */
  }   /* parallel region */
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_jacobi_2d(tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
