static
void kernel_jacobi_2d[[gnu::flatten, gnu::noinline]](int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  /* _PB_N/_PB_TSTEPS may be either the compile-time constants (N/TSTEPS)
     or the runtime values (n/tsteps), depending on how PolyBench is
     configured. We capture them once in local constants for clarity. */
  const int n_inner      = _PB_N;
  const int tsteps_inner = _PB_TSTEPS;

  /* Create restrict-qualified aliases to help the compiler with
     vectorization and to avoid repeatedly computing row offsets.
     The arrays themselves are still n x n; the loop bounds below
     use n_inner exactly as in the original code. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*restrict)[n])A;
  DATA_TYPE (*restrict B_)[n] = (DATA_TYPE (*restrict)[n])B;

  /* Hoist the scalar coefficient out of the loops. */
  const DATA_TYPE c0 = SCALAR_VAL(0.2);

  /* Total number of interior points updated at each sweep.
     Used to avoid OpenMP overhead for very small problem sizes. */
  const long interior_size =
    (long)(n_inner - 2) * (long)(n_inner - 2);
  const int use_parallel =
    (interior_size >= JACOBI_2D_OMP_MIN_SIZE);

#pragma scop
  for (int t = 0; t < tsteps_inner; ++t)
    {
      /* One parallel region per time step, reused for the two sweeps to
         amortize thread creation costs. The 'if' clause lets the code
         run sequentially for very small grids without paying OpenMP
         overhead. When compiled without -fopenmp, all OpenMP pragmas
         are ignored and the code runs sequentially with the same
         semantics as the original version. */
#pragma omp parallel if (use_parallel)
      {
        /* ------------------------------------------------------------------
         * Sweep 1: compute B from A.
         *
         * - Parallelized over rows (i) with OpenMP.
         * - Inside each row, we compute contiguous elements in j, which
         *   maximizes spatial locality and enables SIMD vectorization.
         * - We cache pointers to the current, previous, and next rows of A
         *   to avoid repeated index arithmetic (i*n + j) in the inner loop.
         * ------------------------------------------------------------------ */
#pragma omp for schedule(static)
        for (int i = 1; i < n_inner - 1; ++i)
          {
            DATA_TYPE *restrict Bi      = &B_[i][0];
            DATA_TYPE *restrict Ai      = &A_[i][0];
            DATA_TYPE *restrict Ai_prev = &A_[i-1][0];
            DATA_TYPE *restrict Ai_next = &A_[i+1][0];

