                                     A[i][j-1]   +
                                     A[i][j+1]   +
                                     A[i+1][j]   +
                                     A[i-1][j]); */
                Bi[j] = c0 * (Ai[j] +
                              Ai[j-1] +
                              Ai[j+1] +
                              Ai_next[j] +
                              Ai_prev[j]);
              }
          }

